                getValidatorDatOdDo(povolNull = false, customClass = "") {
                    return new Gordic.Validators.Base({
                        message: "jres:33000431",
                        stopping: true,
                        validate: (value, source) => {
                            var valueOd = "";
                            var valueDo = "";
                            if (customClass == "") {
                                valueOd = this.cnt.findFields("dat_od").gfield("getValue");
                                valueDo = this.cnt.findFields("dat_do").gfield("getValue");
                            }
                            else {
                                valueOd = $(`.${customClass}`).findFields("dat_od").gfield("getValue");
                                valueDo = $(`.${customClass}`).findFields("dat_do").gfield("getValue");
                            }
                            if (valueOd == null || valueOd == undefined)
                                return povolNull == true ? true : false;
                            else if (valueDo == null || valueDo == undefined)
                                return povolNull == true ? true : false;
                            else if (valueOd > valueDo)
                                return false;
                            else
                                return true;
                        }
                    });
                }
