                checkValidatorOdDo() {
                    var val = new Gordic.Validators.Base({ message: "jres:33000551" }); //RC 33000551 : Neplatné nastavení datumu od a do.
                    val.validate = (value, source) => {
                        var datOd = this.cnt.findFields("dat_od").gfield("getValue");
                        var datDo = this.cnt.findFields("dat_do").gfield("getValue");
                        if (datOd && datDo) {
                            if (datOd <= datDo)
                                return true;
                        }
                        return false;
                    };
                    return val;
                }
