                createCisloOdDoValidator() {
                    return new Gordic.Validators.Base({
                        message: "jres:33000042", //RC 33000042 : Evidenční číslo OD musí být menší než evidenční číslo DO.
                        validate: (value, source) => {
                            var acCisloOd = this.cnt.findFields("ac_cislo_od").gfield("getValue");
                            var acCisloDo = this.cnt.findFields("ac_cislo_do").gfield("getValue");
                            if (acCisloOd == null || acCisloOd == undefined)
                                return true;
                            else if (acCisloDo == null || acCisloDo == undefined)
                                return true;
                            else {
                                if (acCisloOd < acCisloDo)
                                    return true;
                                return false;
                            }
                        }
                    });
                }
                acCisloDoValidator(length) {
                    return new Gordic.Validators.Range({
                        stopping: true,
                        max: this.createMaxValue(length),
                        min: 1
                    });
                }
                createMaxValue(length) {
                    var maxstring = "";
                    for (var i = 1; i <= length; i++)
                        maxstring += "9";
                    return parseInt(maxstring);
                }
                rokValidator() {
                    return new Gordic.Validators.Base({
                        message: "jres:33000041".format(1900, 2050), //RC 33000041 : Rok není nastaven v přípustném rozmezí od {0} do {1}.
                        validate: (value, source) => {
                            if (value) {
                                if (value.rok >= 1900 && value.rok <= 2050)
                                    return true;
                            }
                            return false;
                        },
                        stopping: true
                    });
                }
