                createSamePasswordValidator() {
                    return new Gordic.Validators.Base({
                        message: "jres:33001083", //RC 33001083 : Zadaná hesla jsou rozdílná.
                        stopping: true,
                        validate: () => {
                            var passwdFomr = $(".password-form");
                            var passwd1 = passwdFomr.findFields("password").gfield("getValue");
                            var passwd2 = passwdFomr.findFields("password2").gfield("getValue");
                            return passwd1 == passwd2;
                        }
                    });
                }
                getDataFromPasswordForm(ev, ctx, fieldName, formName) {
                    let cnt = $.content(ev.target);
                    let form = cnt.findForms("password-form");
                    var novaData = {};
                    form.gform("waitForValues").done(() => {
                        if (form.gform("isValid")) {
                            return Gordic.Prefabs.GStringBox.updateChiperPublicKeys(form).then(() => {
                                try {
                                    form.findFields().gfield("model", "collect", novaData);
                                }
                                catch (e) {
                                    novaData["zpusob_ulozeni"] = form.findFields("zpusob_ulozeni").gfield("getValue");
                                    novaData["password_map"] = form.findFields("password_map").gfield("getValue");
                                    novaData["password"] = form.findFields("password").gfield("getValue");
                                }
                                var formEl = this.cnt.findForms(formName ?? "{0}form".format(this.options.contentName));
                                if (formEl.length == 0)
                                    formEl = $(".{0}".format(formName ?? "{0}form".format(this.options.contentName)));
                                formEl.findFields(fieldName).gfield("setValue", novaData);
                                cnt.close();
                            });
                        }
                    });
                }
