                        if (that.editMode) // pokud je editacni rezim okna - potom pole jsou obecne pristupna
                            v_readonly = v_field.field_readonly ?? true; // server mi v tom pripade muze prikazat, ze i presto ma byt pole pouze pro cteni
                        // zkusim vytvorit pole validatoru
