            /**
             * metoda pro smazání cache z políčka
             * - např. z Gordic.ControlsLogic.Client.GReaderGinspod
             *
             * @author thazmuka
             * @since 484.1.0.5
             */
            function clearCache(className) {
                if (className == null || className === "") { // null, undefined or empty
                    console.log("Chybí předaná třída pro smazání cache");
                }
                else {
                    var ReaderCache = Gordic.Data.readerCache;
                    ReaderCache.clearCache(className); // smazání cache z Readeru
                }
            }
            Utils.clearCache = clearCache;
