                createTitle() {
                    if (this.options.newRecord == true)
                        return "jres:32000121";
                    if (this.uroven_cfg == 40 || this.uroven_cfg == 60 || this.uroven_cfg == 70 || this.uroven_cfg == 35 || this.uroven_cfg == 50)
                        return "{0} ({1}) - {2}".format(this.options.contentCaption, (this.data.subj_cfg_txt && this.data.subj_cfg_txt) ? this.data.subj_cfg_txt : "", (this.data.param_info?.param_txt && this.data.param_info?.param_txt) ? this.data.param_info.param_txt : "");
                    if (this.uroven_cfg == 20 || this.uroven_cfg == 30 || this.uroven_cfg == 38)
                        return "{0} ({1}) - {2}".format(this.options.contentCaption, (this.data.subj_cfg && this.data.subj_cfg) ? this.data.subj_cfg : "", (this.data.param_info?.param_txt && this.data.param_info?.param_txt) ? this.data.param_info.param_txt : "");
                    else
                        return "{0} - {1}".format(this.options.contentCaption, (this.data.param_info && this.data.param_info.param_txt) ? this.data.param_info.param_txt : "");
                }
