                // Přihlašovací certifikáty
                createCertificateGrid(tab) {
                    this.gridCertificate = $("<div>").appendTo(tab).gautofit({ resizersOnTab: false }).ggrid({
                        columns: new Gordic.Data.GridFormat()
                            .addTextColumn({
                            name: "nazev_cer",
                            caption: "jres:30027574",
                            editor: {
                                widget: "gselectbox",
                                options: $.extend(Gordic.Prefabs.Select.admWflscer(), {
                                    serverFilters: {
                                        priz_int: 1,
                                    },
                                    helperItemTemplate: (row) => {
                                        return "<b>{0}</b><br><span><i>jres:33000176: {1} - {2} | jres:33001903: {3}</i></span>".format(row.jmeno, Gordic.Templates.Formatters.datetime(row.dat_od), Gordic.Templates.Formatters.datetime(row.dat_do), row.otisk); //RC 33001903 : Otisk
                                    },
                                    itemTemplate: (row) => {
                                        return "<b>{0}</b>&nbsp;<i>({1} - {2})</i>".format(row.jmeno, Gordic.Templates.Formatters.datetime(row.dat_od), Gordic.Templates.Formatters.datetime(row.dat_do));
                                    },
                                    name: "ixs_cer",
                                    dropdown: true,
                                    model: "model.ixs_cer=value.ixs_cer;model.nazev_cer=value.jmeno",
                                    validators: [new Gordic.Validators.Required({ stopping: true })]
                                })
                            }
                        })
                            .addTextColumn({
                            name: "poznamka",
                            caption: "jres:29930689",
                            editor: {
                                widget: "gstringbox",
                                options: {
                                    name: "poznamka",
                                }
                            }
                        })
                    }).ggridroweditor({
                        beforeStart: (ev, info) => {
                            if (this.editMode == false)
                                ev.preventDefault();
                        },
                        start: (ev, info) => {
                            if (info.cellInfo.data.ixs_cer)
                                this.cnt.findFields("ixs_cer").gfield("disable");
                        },
                        beforeCommit: (ev, info) => {
                            var currentIxsCers = this.gridCertificate.ggrid("getView").getDataRows(false).map(x => x.ixs_cer);
                            if (info.cellInfo.meta.newRow == false) {
                                if (this.cnt.findFields("ixs_cer").gfield("getValue")) {
                                    var ixs_cer = this.cnt.findFields("ixs_cer").gfield("getValue").ixs_cer;
                                    if (currentIxsCers.includes(ixs_cer) == true)
                                        ev.preventDefault();
                                }
                                else {
                                    ev.preventDefault();
                                }
                            }
                        }
                    });
                    if (this.data.certificates)
                        this.gridCertificate.ggrid("setData", this.data.certificates);
                }
                addLoginCertificate() {
                    this.gridCertificate.ggridroweditor("addRow", { aktivita: 100 });
                }
                updateLoginCertificates() {
                    var selected = this.gridCertificate.ggrid("getSelection");
                    if (selected.length > 0)
                        this.gridCertificate.ggridroweditor("start");
                }
                removeLoginCertificates() {
                    var selected = this.gridCertificate.ggrid("getSelection");
                    if (selected.length > 0) {
                        var certificates = this.gridCertificate.ggrid("getView").getDataRows(false, "data");
                        var index = certificates.findIndex(e => e.ixs_cer == selected[0].ixs_cer);
                        if (index != -1)
                            certificates.splice(index, 1);
                        this.gridCertificate.ggrid("setData", certificates);
                    }
                }
