                updatePassword(ev) {
                    if (this.editMode == false)
                        ev.preventDefault();
                    else {
                        var selected = this.gridExterniUzivatele.ggrid("getSelection");
                        if (selected.length > 0)
                            this.externiUzivateleForm(selected[0]);
                    }
                }
                updatePasswordOk(ev, ctx) {
                    var cnt = $.content(ev.target);
                    var form = cnt.findForms("form-passwd");
                    return Gordic.Prefabs.GStringBox.updateChiperPublicKeys(form).then(() => {
                        form.findFields().gfield("model", "collect", ctx.data, {});
                        ctx.data.new_password = ctx.data.new_passwd;
                        this.getServiceCnt().call("UpdatePasswd", { data: ctx.data }).done((o) => {
                            o.pdb = "****";
                            var currentDataView = this.gridExterniUzivatele.ggrid("getView").getDataRows(false, "data");
                            var index = currentDataView.findIndex(i => i.ldb == o.ldb);
                            if (index != -1) {
                                currentDataView[index].pdb = o.pdb;
                                currentDataView[index].new_password = o.new_password;
                                currentDataView[index].dat_do = o.dat_do;
                                currentDataView[index].aktivita_txt = o.aktivita_txt;
                                currentDataView[index].aktivita = o.aktivita;
                            }
                            cnt.close();
                            this.gridExterniUzivatele.ggrid("setData", currentDataView);
                        });
                    });
                }
