                //#region Propojení s tabulkou (gdevpra)
                createTableGridFormat() {
                    var gridFormat = new Gordic.Data.GridFormat()
                        .addIconColumn({
                        name: "aktivita",
                        caption: "Aktivita",
                        iconTemplate: (row) => {
                            return Gordic.Adm.WebControls.GAdmGridFunctions.createAktivitaCaptionIcon(row["aktivita"]);
                        }
                    })
                        .addTextColumn({
                        name: "tabulka",
                        caption: "Tabulka",
                    })
                        .addTextColumn({
                        name: "sloupec",
                        caption: "Sloupec",
                    })
                        .addTextColumn({
                        name: "poznamka",
                        caption: "Poznámka",
                    });
                    return gridFormat;
                }
                createTableGrid(tab) {
                    this.gridTable = $(tab).appendTo(this.element).gautofit().ggrid({
                        columnMode: "fit",
                        columns: this.createTableGridFormat(),
                        rowsEnabled: (metadata) => {
                            if (metadata.data.aktivita == 100 || metadata.data.aktivita == 300)
                                return true;
                            return false;
                        },
                        defaultProfile: {
                            sort: "aktivita",
                        },
                        defaultAction: this.actions.actEditTableDialog,
                        cellActivate: (ev, ctx) => {
                            if (ctx != null && ctx.cellInfo != null && ctx.cellInfo.data != null) {
                                if (ctx.cellInfo.data.aktivita == 900) { // zrušen
                                    this.actions.actDeactivateTable?.update({ enabled: false });
                                    this.actions.actActivateTable?.update({ enabled: true });
                                }
                                else if (ctx.cellInfo.data.aktivita == 100) { // aktivní
                                    this.actions.actDeactivateTable?.update({ enabled: true });
                                    this.actions.actActivateTable?.update({ enabled: false });
                                }
                                else if (ctx.cellInfo.data.aktivita == 300 || ctx.cellInfo.data.aktivita == 500 || ctx.cellInfo.data.aktivita == 600) { // připraven, neaktivní, návrh
                                    this.actions.actDeactivateTable?.update({ enabled: true });
                                    this.actions.actActivateTable?.update({ enabled: true });
                                }
                                else { // cokoliv jiného - např. prázdný grid
                                    this.actions.actDeactivateTable?.update({ enabled: false });
                                    this.actions.actActivateTable?.update({ enabled: false });
                                }
                            }
                        }
                    });
                }
                setDataToTableGrid() {
                    this.beginOperation();
                    this.isl.VPravidlo.list({ filters: { pravidlo_id: this.data.pravidlo_id } }).getView().done((data) => {
                        this.gridTable.ggrid("setData", data);
                    }).always(() => { this.endOperation(); });
                }
