                constructor() {
                    super(...arguments);
                    this.generovaniTransProtokoluAsyncTask = "Gordic.AdmIsl.Server.GGenerovaniTransProtokoluAsync";
                    this.generovaniTransProtokolTaskId = "generovaniTransProtokol";
                }
