                setEditMode(editMode) {
                    this.setEditModeTab(editMode, $(".tab-group-_tab-parametry-kroku"));
                    if (this.data.typ_krok == 10070) {
                        var form = this.cnt.findForms("automaticke-vytvoreni-spisu");
                        var rok_spz_aktual = form.findFields("rok_spz_aktual").gfield("getValue");
                        var ixs_typ_aktual = form.findFields("ixs_typ_aktual").gfield("getValue");
                        form.findFields("rok_spz").gfield(rok_spz_aktual == true ? "disable" : "enable");
                        form.findFields("rok_spz").gfield("setValidators", rok_spz_aktual == true ? [] : [new Gordic.Validators.Required({ stopping: true })]);
                        form.findFields("ixs_typ").gfield(ixs_typ_aktual == true ? "disable" : "enable");
                        form.findFields("ixs_typ").gfield("setValidators", ixs_typ_aktual == true ? [] : [new Gordic.Validators.Required({ stopping: true })]);
                    }
                    else if (this.data.typ_krok == 10050) {
                        var form = this.cnt.findForms("automaticke-zalozeni-cj");
                        var rok_cj_aktual = form.findFields("rok_cj_aktual").gfield("getValue");
                        form.findFields("rok_cj").gfield(rok_cj_aktual == true ? "disable" : "enable");
                        form.findFields("rok_cj").gfield("setValidators", rok_cj_aktual == true ? [] : [new Gordic.Validators.Required({ stopping: true })]);
                    }
                }
                createForm() {
                    this.data.parametry_kroku_trasy;
                    this.form.form.layoutDescriptor = "L2M2S1";
                    this.MakeSection("");
                    this.MakeSelectField("ixs_tra", Gordic.Prefabs.Select.wflstra(), { model: "model.ixs_tra=value.ixs_tra" });
                    this.MakeField("poradi");
                    this.MakeSelectField("typ_krok", Gordic.Prefabs.Select.admWflctkr(), {
                        model: "model.typ_krok=value.typ_krok",
                        dropdown: true,
                        serverFilters: {
                            typ_krok: this.parametry_forms.map((item) => item.id)
                        },
                        change: (ev, obj) => {
                            var tab = $(".tab-group-_tab-parametry-kroku");
                            tab.children().hide();
                            if (obj.value != null && obj.value != undefined) {
                                var objTmp = obj.value;
                                if (!Array.isArray(obj)) {
                                    var form = this.parametry_forms.find(item => item.id == objTmp.typ_krok);
                                    var formEl = tab.findForms((form?.name != undefined && form?.name != null) ? form?.name : "");
                                    formEl.show();
                                    if (this.data.parametry_kroku_trasy) {
                                        var inputData = form?.convertData(this.data.parametry_kroku_trasy);
                                        formEl.findFields().gfield("model", "apply", inputData);
                                    }
                                    if (objTmp.typ_krok == 0) {
                                        this.cnt.findFields("ixs_fun_pov").gfield("setValidators", [new Gordic.Validators.Required({ stopping: true })]);
                                    }
                                    else {
                                        this.cnt.findFields("ixs_fun_pov").gfield("setValidators", []);
                                    }
                                }
                            }
                            else {
                                this.cnt.findFields("ixs_fun_pov").gfield("setValidators", []);
                            }
                        }
                    });
                    this.MakeField("nazev");
                    this.MakeField("dnu_termin", {
                        validators: [new Gordic.Validators.Range({ stopping: true, min: 0 })]
                    });
                    this.MakeBoolField("typ_dnu_termin");
                    this.MakeSection(""); //RC 33000801 : Pověřená osoba - nositel (realizátor) úkolu
                    this.MakeSelectField("ixs_su_pov", Gordic.Prefabs.Select.ginspod(Gordic.Adm.WebControls.GAdmGlobals.createSpecialSelectorGinspod()), {
                        model: "model.ixs_su_pov=value.ixs_su",
                        graphicInput: "oninput",
                        itemTemplate: (row) => { return Gordic.Adm.WebControls.GAdmGlobals.createSpecialItemTemplateGinspod(row ?? {}); },
                    });
                    this.MakeSelectField("ixs_fun_pov", Gordic.Prefabs.Select.admGinsfun(), {
                        model: "model.ixs_fun_pov=value.ixs_fun",
                        dropdown: false
                    });
                    this.MakeSelectField("aktivita", Gordic.Prefabs.Select.gincakt());
                    this.MakeField("dat_zmena");
                    this.MakeSelectField("zmenu_prov", Gordic.Prefabs.Select.ginszmp(), { model: "model.zmenu_prov=value.ixs_zmp" });
                }
